-- Step 3: Final verification
SELECT p.program_name,
       p.total_core_sch/3 as expected_slots,
       p.num_core_courses as db_slots,
       COUNT(DISTINCT pcc.id) as db_rows,
       COUNT(DISTINCT CASE WHEN pcc.or_group_id>0 THEN pcc.or_group_id END) as or_groups,
       CASE WHEN p.num_core_courses=p.total_core_sch/3 THEN 'OK' ELSE 'MISMATCH' END as status
FROM programs p
LEFT JOIN program_core_courses pcc ON pcc.program_id=p.id
WHERE p.total_core_sch > 0
GROUP BY p.id, p.program_name, p.total_core_sch, p.num_core_courses
ORDER BY status DESC, p.program_name;

